package net.hivel.islandsrpg.util;
import org.bukkit.*; import org.bukkit.configuration.file.FileConfiguration; import org.bukkit.plugin.java.JavaPlugin;
public final class LocationUtil { private LocationUtil(){} public static Location parse(JavaPlugin p,String s){ try{String[] a=s.split(","); if(a.length<4)return null; World w=Bukkit.getWorld(a[0]); if(w==null)return null; double x=Double.parseDouble(a[1]), y=Double.parseDouble(a[2]), z=Double.parseDouble(a[3]); float yaw=a.length>4?Float.parseFloat(a[4]):0, pitch=a.length>5?Float.parseFloat(a[5]):0; return new Location(w,x,y,z,yaw,pitch);}catch(Exception e){p.getLogger().warning("Invalid location: "+s); return null;}} public static String serialize(Location l){return l.getWorld().getName()+","+l.getX()+","+l.getY()+","+l.getZ()+","+l.getYaw()+","+l.getPitch();} }
